CREATE TABLE IF NOT EXISTS service_content_sections (
  id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
  service_id VARCHAR(191) NOT NULL,
  section_key VARCHAR(100) NOT NULL,
  eyebrow VARCHAR(255) NULL,
  heading VARCHAR(500) NOT NULL,
  body LONGTEXT NULL,
  display_order INT NOT NULL DEFAULT 0,
  created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (id),
  UNIQUE KEY uq_service_content_section_key (service_id, section_key),
  KEY idx_service_content_sections_order (service_id, display_order),
  CONSTRAINT fk_service_content_sections_service FOREIGN KEY (service_id) REFERENCES services (id) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS service_content_items (
  id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
  section_id BIGINT UNSIGNED NOT NULL,
  title VARCHAR(500) NOT NULL,
  description TEXT NOT NULL,
  details TEXT NULL,
  display_order INT NOT NULL DEFAULT 0,
  created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (id),
  UNIQUE KEY uq_service_content_item_order (section_id, display_order),
  CONSTRAINT fk_service_content_items_section FOREIGN KEY (section_id) REFERENCES service_content_sections (id) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;

